import{_ as o,o as a,c as i,a2 as t}from"./chunks/framework.BN2sqjC1.js";const m=JSON.parse('{"title":"Checklist manuale M0 — \\"Hello vault\\" con login","description":"","frontmatter":{},"headers":[],"relativePath":"qa/m0-checklist.md","filePath":"qa/m0-checklist.md"}'),l={name:"qa/m0-checklist.md"};function c(n,e,r,s,d,u){return a(),i("div",null,[...e[0]||(e[0]=[t('<h1 id="checklist-manuale-m0-—-hello-vault-con-login" tabindex="-1">Checklist manuale M0 — &quot;Hello vault&quot; con login <a class="header-anchor" href="#checklist-manuale-m0-—-hello-vault-con-login" aria-label="Permalink to &quot;Checklist manuale M0 — &quot;Hello vault&quot; con login&quot;">​</a></h1><p>Da eseguire su macOS (sviluppo) e, prima di chiudere M0, almeno una volta su Windows e Linux con gli artefatti della CI. Spuntare con data e OS.</p><h2 id="stack-e-cloud" tabindex="-1">Stack e cloud <a class="header-anchor" href="#stack-e-cloud" aria-label="Permalink to &quot;Stack e cloud&quot;">​</a></h2><ul><li>[ ] <code>task stack-up</code> porta a healthy PostgreSQL (5433), RustFS (9000/9001), Keycloak (8080); <code>task stack-reset</code> re-importa il realm.</li><li>[ ] <code>task dev-cloud</code>: log &quot;database migrated&quot;, &quot;oidc issuer ready&quot;, &quot;http listening&quot; su 18081, &quot;grpc listening&quot; su 18082.</li><li>[ ] <code>curl localhost:18081/api/v1/healthz</code> → 200; <code>/readyz</code> → <code>database: ok</code>; <code>/me</code> senza token → 401 problem+json con <code>request_id</code>.</li><li>[ ] <code>task test-integration</code> verde (testcontainers).</li></ul><h2 id="desktop" tabindex="-1">Desktop <a class="header-anchor" href="#desktop" aria-label="Permalink to &quot;Desktop&quot;">​</a></h2><ul><li>[ ] <code>task dev-desktop</code> apre la finestra &quot;MemoBrain Notes&quot; con la schermata di benvenuto nella lingua di sistema (it/en).</li><li>[ ] &quot;Apri cartella come vault&quot; → picker nativo → l&#39;albero mostra file e cartelle; <code>.DS_Store</code>, <code>.memobrain/cache</code> non compaiono.</li><li>[ ] Nuova nota → appare nell&#39;albero e si apre nell&#39;editor; digitare → &quot;Salvato&quot; entro ~1 s; il file su disco contiene il testo; nessun file <code>.memobrain-tmp-*</code> residuo.</li><li>[ ] Modificare la nota aperta con un editor esterno → banner di conflitto; &quot;Ricarica&quot; mostra il contenuto esterno; &quot;Sovrascrivi&quot; lo sostituisce.</li><li>[ ] Creare/rinominare/eliminare file dall&#39;esterno → l&#39;albero si aggiorna entro ~2 s (watcher).</li><li>[ ] Ricerca: 3+ caratteri trovano sottostringhe nel corpo e nel titolo, con snippet evidenziato; &lt; 3 caratteri nessun risultato.</li><li>[ ] Impostazioni: cambio lingua e tema applicati subito e persistenti al riavvio; &quot;Informazioni&quot; mostra versione e cartella dati.</li><li>[ ] Riavvio: il vault compare tra i recenti e si riapre.</li><li>[ ] Seconda istanza (<code>memobrain --data-dir &lt;altra&gt;</code>) coesiste; seconda istanza con la <strong>stessa</strong> data dir porta in primo piano la prima.</li><li>[ ] URL scheme: <code>open &quot;memobrain://open?vault=X&amp;file=Y&quot;</code> (macOS) con app aperta → evento <code>app:open-request</code> nel log; con app chiusa → l&#39;app parte (richiede build installata in /Applications per la registrazione dello scheme).</li><li>[ ] Build di produzione (<code>task build-desktop</code>): l&#39;app si avvia, nessun errore CSP nella console del webview (Safari → Sviluppo → MemoBrain Notes).</li></ul><h2 id="login-m0-wp6" tabindex="-1">Login (M0-WP6) <a class="header-anchor" href="#login-m0-wp6" aria-label="Permalink to &quot;Login (M0-WP6)&quot;">​</a></h2><ul><li>[ ] &quot;Accedi al cloud&quot; apre il browser di sistema su Keycloak; login <code>user1</code> / <code>memobrain-dev-password</code> → ritorno all&#39;app, profilo visibile; refresh token nel keychain (Accesso Portachiavi: voce &quot;MemoBrain Notes&quot;).</li><li>[ ] Con listener loopback bloccato (es. <code>MEMOBRAIN_AUTH_REDIRECT=scheme</code>) il login usa <code>memobrain://auth/callback</code>.</li><li>[ ] Sospendere l&#39;utente da Keycloak → entro 30 s le chiamate falliscono con <code>USER_SUSPENDED</code>; il lavoro locale continua.</li></ul>',8)])])}const h=o(l,[["render",c]]);export{m as __pageData,h as default};
